import { EnvelopeModeController } from './modules/envelopeMode/envelopeModeController.js';
import { mountSettings, openSettings } from './modules/settings/settingsSurface.js';

export function initUI() {
    setupMainButtons();
    setupControlSliders();

    setupWaveformSelector();
    setupSelectSteppers();

    setupDrawbars();
    setupSpectralSystem();
    setupVisualizations();
    setupFundamental();
    setupSurfaces();

    // Initialize keyboard shortcuts
    new KeyboardShortcuts().init();

    // Cmd/Ctrl = link (an edit goes to every voice), Shift = shape (an
    // edit sculpts every voice along a contour)
    initLinkAll();
    initShapeMode();

    // OSC over WebSocket: the remote-control path for jweb/Max4Live, where
    // Web MIDI delivery is starved while the view is hidden (?osc=0 disables).
    // The shared instance was already bootstrapped with cached state by app.js.
    if (oscEnabled()) {
        oscClient.init();
    }

    setupPulseOutputs();

    setTimeout(() => {
        // if midi is firing while the components are still rendering it breaks the p5 sketch :-/
        midiInputRouter.init();
        midiOutputRouter.init(); // no-op where Web MIDI is unavailable (jweb)
    }, 2000);
}

/**
 * Voice cycle pulses (gate worklets) → pulse bus → MIDI / OSC / JS.
 * OSC relay sends only audible (gate-open) cycles, matching what you hear.
 */
function setupPulseOutputs() {
    setPulseHandler((index, pulse) => pulseBus.dispatch(index, pulse));
    pulseBus.addSink((index, pulse) => {
        const oscOn = AppState.oscillatorPulseOuts[index]?.osc ?? midiConfig.pulseOscEnabled;
        if (oscOn && pulse.gateOn) {
            oscClient.emitPulse(index, pulse);
        }
    });
}

function setupDrawbars() {
    const drawbarsController = new DrawbarsController("#drawbars");
    drawbarsController.init();
    // The strip's bottom bar: reset/randomize act on the showing family
    const toolbar = new OvertoneToolbarController('#drawbars-toolbar', {
        onReset: () => drawbarsController.reset(),
        onRandomize: () => drawbarsController.randomize(),
    });
    toolbar.init();
    // The bank's filter multiplier lives in the strip's footer — one
    // control over all twelve columns, so it belongs to the bar rather
    // than to a column. Disabled in place on the other three families.
    const multiplier = mountFilterMultiplier(toolbar.slotEl);
    const syncMultiplierFamily = () => multiplier.setFamily(drawbarsController.family);
    document.addEventListener(SURFACE_CHANGED, syncMultiplierFamily);
    syncMultiplierFamily();
    // Retuning the bank puts the multiplier back on the heuristic, whether
    // or not the synth is playing (the audio path only runs when it is)
    for (const event of [FUNDAMENTAL_CHANGED, SPECTRAL_SYSTEM_CHANGED, SUBHARMONIC_TOGGLED]) {
        document.addEventListener(event, () => OvertoneSignalActions.refreshFilterMultiplier());
    }
    // …and once now: the bridge bootstrap has already applied whatever
    // fundamental and system this session starts on, without events
    OvertoneSignalActions.refreshFilterMultiplier();
}

function setupSpectralSystem() {
    new SpectralSystemController("#spectral-system-root").init();
    new TonewheelController("#tonewheel-container").init();
}

/** The side-column visualizations, one per parameter surface. */
function setupVisualizations() {
    // Gain: the summed wavetable + bake/export actions
    new WaveformController("#waveform-canvas-area").init();
    new DownloadControlController("#routing-control-root").init();
    // Filter: the live output
    new ScopeController("#scope-canvas-area").init();
    // Convolution: the spectrum (Create IR bakes it) — see setupWaveformSelector
    // ADSR: every voice's envelope
    new EnvelopeVizController("#envelope-canvas-area").init();
    new SequenceVizController("#sequence-canvas-area").init();
}

function setupFundamental() {
    new FundamentalController("#fundamental-control-root").init();
    // Trigger surface: one pad per overtone
    new PadGridController('#pad-grid').init();
}

function setupSurfaces() {
    // After every panel is mounted (and its canvases sized while visible),
    // so the shell can hide the ones the default surface doesn't show
    new SurfacesController('#surface-toolbar', '.page-content', '.side-toggle-btn').init();
    // The Sequence panel's bottom bar: reset/randomize act on every
    // voice's gate; its slot carries the inspector's voice stepper
    new OvertoneToolbarController('#sequence-toolbar', {
        onReset: () => OvertoneSignalActions.resetGates(),
        onRandomize: () => OvertoneSignalActions.randomizeGates(),
    }).init();
    // The per-overtone sequence editor
    // The ‹ Overtone N › stepper sits top and center of the panel
    new InspectorController('#sequence-inspector', document.getElementById('sequence-voice')).init();
    // Link and shape are tools of the per-overtone surfaces: leaving them
    // drops both
    document.addEventListener(SURFACE_CHANGED, () => {
        if (surfaceState.tools) return;
        shapeMode.reset();
        linkLock.set(false);
    });
    // The preset banks and their dirty tracking load now (a MIDI
    // crossfade must work before the panel is ever opened); the panel
    // itself, like Settings, is built the first time it is shown —
    // together they are ~28 kB of code and a few hundred nodes that most
    // sessions never look at.
    initPresets();
    document.addEventListener(SURFACE_CHANGED, () => mountPanelFor(surfaceState.active));
}

/** Panels built on first show: id → the mount, run once. */
const LAZY_PANELS = {
    presets: async () => {
        const [{ PresetsController }, { PresetsComponent }] = await Promise.all([
            import('./modules/presets/presetsController.js'),
            import('./modules/presets/PresetsComponent.js'),
        ]);
        new PresetsController('#presets-control-root', PresetsComponent).init();
    },
    // Settings owns its own mount (settingsSurface.js), because the things
    // that open it are modules ui.js itself imports
    settings: () => mountSettings(),
};
const mounted = new Map();

/** Build a lazy panel if this surface has one; resolves once it is up. */
export function mountPanelFor(surfaceId) {
    const mount = LAZY_PANELS[surfaceId];
    if (!mount) return Promise.resolve();
    if (!mounted.has(surfaceId)) mounted.set(surfaceId, mount());
    return mounted.get(surfaceId);
}

function setupMainButtons() {
    new PlayToggleController('.play-toggle-container').init();
    setupEnvelopeMode();
    const recorder = new RecorderController('#recorder-root');
    // The ⚙ can be the first thing that ever needs the settings panel
    recorder.onOpenSettings = () => openSettings('recorder');
    recorder.init();
}

/**
 * Trigger/Drone mode: Drone = every voice sounds freely; Trigger = voices
 * rest silent and are gated per overtone (pads, Q-] keys, the strip's
 * trigger pads). The switch lives in the navbar; body.adsr-mode drives
 * the strip pads' visibility in CSS.
 */
function setupEnvelopeMode() {
    new EnvelopeModeController('#navbar-mode-root').init();
    const sync = () => {
        document.body.classList.toggle('adsr-mode', OvertoneSignalActions.getEnvelopeMode() === 'adsr');
    };
    document.addEventListener(ENVELOPE_MODE_CHANGED, sync);
    sync(); // bootstrap may have applied a bridged mode before init
}

function setupControlSliders() {
    // Master Gain Slider
    const gainSlider = new SliderController('#master-gain-slider-root', {
        min: 0,
        max: 1,
        step: 0.01,
        value: AppState.masterGainValue,
        label: 'Gain',
        ariaLabel: 'Master gain',
        formatValue: (v) => `${(v * 100).toFixed(0)}%`,
    }, (value) => {
        smoothUpdateMasterGain(value);
    });
    gainSlider.init();

    // Master Slew Slider
    const slewSlider = new SliderController('#master-slew-slider-root', {
        min: 0,
        max: 10,
        step: 0.01,
        value: AppState.masterSlewValue,
        label: 'Slew',
        ariaLabel: 'Master slew',
        formatValue: (v) => {
            v = parseFloat(v);
            let displayValue = (v * 1000).toFixed(0);
            let unit = 'ms';
            if (v > 1) {
                displayValue = v.toFixed(2);
                unit = 's';
            }
            return `${displayValue}${unit}`;
        }
    }, (value) => {
        updateAppState({ masterSlewValue: value });
        document.dispatchEvent(new CustomEvent(MASTER_SLEW_CHANGED, { detail: { value } }));
    });
    slewSlider.init();

    // Both follow changes made elsewhere (a preset recall, a crossfade, the
    // bridge); a slider's own write lands on the value it already shows
    const follow = (slider, read) => () => {
        if (Math.abs(parseFloat(slider.component.input.value) - read()) > 1e-9) slider.setValue(read());
    };
    document.addEventListener(MASTER_GAIN_CHANGED, follow(gainSlider, () => AppState.masterGainValue));
    document.addEventListener(MASTER_SLEW_CHANGED, follow(slewSlider, () => AppState.masterSlewValue));

    // Narrow layouts move the two into the rail down the right edge
    new MasterRailController('#master-rail', '.navbar-section.center',
        ['#master-gain-slider-root', '#master-slew-slider-root']).init();
}

// ================================
// SOURCE
// ================================

function setupWaveformSelector() {
    new SourceController('#oscillator-control-root').init();
    // The chosen oscillator's own cycle, previewed in the Source panel
    new WaveformController("#current-waveform-canvas-area", { mode: "single" }).init();

    // Spectral view of the timbre as Create IR will bake it (ring-aware)
    new SpectrumController('#spectrum-canvas-area').init();

    new WaveformSelectorController('#waveform-select').init();
}

/**
 * Next/previous buttons flanking select menus. Native dropdowns don't open
 * inside Max's jweb object, so these are the only way to switch options there.
 */
function setupSelectSteppers() {
    document.querySelectorAll('.select-step-btn').forEach((btn) => {
        btn.addEventListener('click', () => {
            const select = document.getElementById(btn.dataset.target);
            if (!select || select.options.length === 0) return;
            const step = parseInt(btn.dataset.step, 10) || 1;
            const count = select.options.length;
            // Skip what isn't a choice: display-only entries (the waveform
            // menu's "Interpolated", the sampler's "no file" placeholder)
            // and entries that run an action instead of selecting a value
            // ("Manage files…"). A menu can be ALL of those — an empty
            // library — so the walk is bounded rather than a do/while that
            // would spin the page.
            const skip = (option) => option.disabled || option.dataset.role === 'action';
            let index = select.selectedIndex;
            for (let taken = 0; taken < count; taken++) {
                index = (index + step + count) % count;
                if (!skip(select.options[index])) {
                    select.selectedIndex = index;
                    select.dispatchEvent(new Event('change', { bubbles: true }));
                    return;
                }
            }
        });
    });
}


/**
 * Updates all UI elements to reflect current state
 * TODO: remove this and use individual components
 */
export function updateUI() {

    // Update waveform selector
    updateValue('waveform-select', AppState.waveformMorph ? '' : AppState.currentWaveform);
}
